package com.primehr.security;
import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class Phase6c3PermissionGuardTest {
 @Test void submitApproveAndFinalizeRemainIndependent(){AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);PerformanceCommitmentPermissionGuard guard=new PerformanceCommitmentPermissionGuard(client);when(client.resolve(PerformanceCommitmentPermissionGuard.INDIVIDUAL,"t")).thenReturn(new EffectiveFeaturePermission(PerformanceCommitmentPermissionGuard.INDIVIDUAL,false,true,false,false,false,false,true,false,false,false,false,PermissionDataScope.OWN_RECORDS));assertThat(guard.require("IPCR",PrimeHrAction.SUBMIT,"t")).isEqualTo(PermissionDataScope.OWN_RECORDS);assertThatThrownBy(()->guard.require("IPCR",PrimeHrAction.APPROVE,"t")).isInstanceOf(AccessDeniedException.class);when(client.resolve(PerformanceCommitmentPermissionGuard.INDIVIDUAL,"t")).thenReturn(new EffectiveFeaturePermission(PerformanceCommitmentPermissionGuard.INDIVIDUAL,false,true,false,false,false,false,false,true,false,false,false,PermissionDataScope.ASSIGNED_RECORDS));assertThat(guard.require("IPCR",PrimeHrAction.APPROVE,"t")).isEqualTo(PermissionDataScope.ASSIGNED_RECORDS);assertThatThrownBy(()->guard.require("IPCR",PrimeHrAction.FINALIZE,"t")).isInstanceOf(AccessDeniedException.class);}
}
